5	
6	export interface PracticeFlashcardData {
7	  front: string;
8	  back: string;
9	  subtitle?: string;
10	  tag?: string;
11	  tagColor?: string;
12	  /** P0-4: heritage as a text chip on the back — color stays a secondary channel. */
13	  heritageLabel?: string;
14	}
15	
16	interface PracticeFlashcardProps {
17	  card: PracticeFlashcardData;
18	  ratingLabels: Record<PracticeRating, { uk: string; en: string }>;
19	  intervalPreviews: Record<PracticeRating, string>;
20	  onRate(rating: PracticeRating): void;
21	  /** Pure chrome locale for rating-button labels (#5503). */
22	  chromeLocale: ChromeLocale;
23	}
24	
25	const RATING_ORDER: PracticeRating[] = ['again', 'hard', 'good', 'easy'];
26	
27	export default function PracticeFlashcard({
28	  card,
29	  ratingLabels,
30	  intervalPreviews,
31	  onRate,
32	  chromeLocale,
33	}: PracticeFlashcardProps) {
34	  const [flipped, setFlipped] = useState(false);
35	  const [rated, setRated] = useState(false);
36	
37	  useEffect(() => {
38	    setFlipped(false);
39	    setRated(false);
40	  }, [card.front, card.back]);
41	
42	  const tapLabel = CHROME_STRINGS[chromeLocale]['practice.tapToFlip'];
43	  const rateRecallLabel = CHROME_STRINGS[chromeLocale]['practice.rateRecall'];
44	  const flipHint = CHROME_STRINGS[chromeLocale]['practice.flipHint'];
45	  const rateAfterFlipHint = CHROME_STRINGS[chromeLocale]['practice.rateAfterFlipHint'];
46	  const keyShortcutWord = CHROME_STRINGS[chromeLocale]['practice.keyShortcutWord'];
47	  const intervalPrefix = CHROME_STRINGS[chromeLocale]['practice.intervalPrefix'];
48	
49	  useEffect(() => {
50	    const onKeyDown = (event: KeyboardEvent) => {
51	      if (rated) return;
52	      if (event.altKey || event.ctrlKey || event.metaKey) return;
53	      // Never steal keys from text-entry controls (typing 'a' must not rate).
54	      const target = event.target as HTMLElement | null;
55	      if (target?.closest?.('input, textarea, select, [contenteditable="true"]')) return;
56	      const key = event.key.toLowerCase();
57	      // Space/Enter activate whatever control holds focus (button, link, the card
58	      // itself) — let that native activation happen instead of double-handling it here.
59	      const activatesControl = key === ' ' || key === 'enter';
60	      if (activatesControl && target?.closest?.('button, a, [role="button"], [role="link"]')) return;
61	      if (!flipped && (key === ' ' || key === 'enter')) {
62	        event.preventDefault();
63	        setFlipped(true);
64	        return;
65	      }
66	      if (!flipped) return;
67	      const rating =
68	        key === 'a' || key === '1'
69	          ? 'again'
70	          : key === 'h' || key === '2'
71	            ? 'hard'
72	            : key === 'g' || key === '3'
73	              ? 'good'
74	              : key === 'e' || key === '4'
75	                ? 'easy'
76	                : null;
77	      if (!rating) return;
78	      event.preventDefault();
79	      setRated(true);
80	      onRate(rating);
81	    };
82	    window.addEventListener('keydown', onKeyDown);
83	    return () => window.removeEventListener('keydown', onKeyDown);
84	  }, [flipped, rated, onRate]);
85	
86	  const handleFlip = () => {
87	    if (rated) return;
88	    setFlipped((value) => !value);
89	  };
90	
91	  const handleRate = (rating: PracticeRating) => {
92	    if (!flipped || rated) return;
93	    setRated(true);
94	    onRate(rating);
95	  };
96	
97	  return (
98	    <>
99	      <div
100	        className={`flashcard${flipped ? ' flipped' : ''}`}
101	        data-activity="flashcard"
102	        data-flipped={flipped ? 'true' : 'false'}
103	        data-rated={rated ? 'true' : 'false'}
104	        onClick={handleFlip}
105	        onKeyDown={(event) => {
106	          if (rated) return;
107	          if (event.key === 'Enter' || event.key === ' ') {
108	            event.preventDefault();
109	            handleFlip();
110	          }
111	        }}
112	        role="button"
113	        tabIndex={rated ? -1 : 0}
114	        aria-label={flipped ? `${card.back} — ${tapLabel}` : `${card.front} — ${tapLabel}`}
115	      >
116	        <div className="flashcard-inner">
117	          <div className="flashcard-front">
118	            <span className="flashcard-word">{card.front}</span>
119	            {card.subtitle && <span className="flashcard-subtitle">{card.subtitle}</span>}
120	            {card.tag && (
121	              <span
122	                className="flashcard-tag"
123	                style={card.tagColor ? { background: card.tagColor, color: 'white' } : undefined}
124	              >
125	                {card.tag}
126	              </span>
127	            )}
128	            {!flipped && <span className="flashcard-flip-hint">{flipHint}</span>}
129	          </div>
130	          <div className="flashcard-back">
131	            <span className="flashcard-word">{card.back}</span>
132	            {card.subtitle && <span className="flashcard-subtitle">{card.subtitle}</span>}
133	            {(card.tag || card.heritageLabel) && (
134	              <span className="flashcard-back-tags">
135	                {card.tag && (
136	                  <span
137	                    className="flashcard-tag"
138	                    style={card.tagColor ? { background: card.tagColor, color: 'white' } : undefined}
139	                  >
140	                    {card.tag}
141	                  </span>
142	                )}
143	                {card.heritageLabel && (
144	                  <span
145	                    className="flashcard-heritage-chip"
146	                    style={card.tagColor ? { borderColor: card.tagColor } : undefined}
147	                  >
148	                    {card.heritageLabel}
149	                  </span>
150	                )}
151	              </span>
152	            )}
153	          </div>
154	        </div>
155	      </div>
156	      <div
157	        className="lexicon-rating-bar rating-bar"
158	        role="group"
159	        aria-label={rateRecallLabel}
160	        data-revealed={flipped ? 'true' : 'false'}
161	        data-locked={rated ? 'true' : 'false'}
162	      >
163	        {!flipped && <p className="rating-bar-hint">{rateAfterFlipHint}</p>}
164	        {RATING_ORDER.map((rating, index) => (
165	          <button
166	            type="button"
167	            key={rating}
168	            className="rate-btn"
169	            data-rate={rating}
170	            aria-keyshortcuts={String(index + 1)}
171	            disabled={!flipped || rated}
172	            aria-disabled={!flipped || rated}
173	            onClick={() => handleRate(rating)}
174	          >
175	            <span className="rk" aria-label={`${keyShortcutWord} ${index + 1}`}>
176	              {index + 1}
177	            </span>
178	            <span className="rt" lang={chromeLocale}>
179	              {ratingLabels[rating][chromeLocale]}
180	            </span>
181	            {flipped ? (
182	              <span className="ri">
183	                {intervalPrefix} {intervalPreviews[rating]}
184	              </span>
185	            ) : null}
186	          </button>
187	        ))}
188	      </div>
189	    </>
190	  );
191	}

