33	  new: { glyph: '↻', labelKey: 'practice.statusNew' as const, colorVar: 'var(--lu-blue)' },
34	  done: { glyph: '✓', labelKey: 'practice.statusDone' as const, colorVar: 'var(--lu-green)' },
