60	
61	  const total = snapshot.items.length;
62	  const currentItem = orderedRows[previewIndex]?.item ?? null;
63	  const currentLemmaId = currentItem?.lemmaId ?? null;
64	  // The practice-lexemes map is OPTIONAL ENRICHMENT ONLY (ipa, and pos/example
65	  // when the pick payload itself lacks them) — most daily-pool picks are not
66	  // in this much smaller map, so the card must never depend on a hit here to
67	  // render (#5852), nor let a map hit override the pick's own data (#5856).
68	  const currentLexeme = currentLemmaId ? lexemes.get(currentLemmaId) ?? null : null;
69	
70	  const handlePrevious = () => {
71	    setFlipped(false);
72	    setPreviewIndex((index) => (index > 0 ? index - 1 : total - 1));
73	  };
74	
75	  const handleNext = () => {
76	    setFlipped(false);
77	    setPreviewIndex((index) => (index < total - 1 ? index + 1 : 0));
78	  };
79	
80	  const handleFlip = () => {
