89	  const frontSubtitle = currentItem
90	    ? [currentLexeme?.ipa, displayPos, displayCefr].filter(Boolean).join(' · ')
91	    : '';
92	  const showStressMarks = learnerLevel === 'A1';
93	  const displayLemma = (lemma: string) => (showStressMarks ? lemma : stripStressMarks(lemma));
94	  const currentExample = currentItem?.example?.trim() || currentLexeme?.example?.trim() || null;
95	  const currentExampleEn = usablePracticeSentenceEnglish(currentItem?.exampleEn || currentLexeme?.exampleEn);
96	  const currentEtymology = currentItem?.etymology?.trim() || null;
97	
98	  return (
99	    <div className="practice-daily-deck" data-testid="practice-daily-deck">
100	      <div className="daily-deck-header">
101	        <h2 data-testid="practice-daily-deck-title">
102	          {deckTitleUk && deckTitleEn ? (
103	            <ChromeDual
104	              uk={`Слова дня — ${deckTitleUk}`}
105	              en={`Words of the day — ${deckTitleEn}`}
106	            />
107	          ) : (
108	            <ChromeText k="practice.wordsTitle" />
109	          )}
110	        </h2>
111	        <span className="daily-deck-position" aria-live="polite">
112	          <ChromeDual
113	            uk={`${previewIndex + 1} з ${total}`}
114	            en={`${previewIndex + 1} / ${total}`}
115	          />
116	        </span>
117	        {onReRoll ? (
118	          <button
119	            type="button"
120	            className="daily-deck-reroll"
121	            data-testid="practice-daily-reroll"
122	            onClick={() => {
123	              setPreviewIndex(0);
124	              setFlipped(false);
125	              onReRoll();
126	            }}
127	          >
128	            <span aria-hidden="true">🔀</span> <ChromeText k="practice.reRoll" />
129	          </button>
130	        ) : null}
131	      </div>
132	
133	      <div className="daily-deck-preview-shell">
134	        <button
135	          type="button"
136	          className="daily-deck-nav"
137	          aria-label={chromeString(chromeLocale, 'label.previous')}
138	          onClick={handlePrevious}
139	        >
140	          ‹
141	        </button>
142	
143	        <div
144	          className={`flashcard daily-preview-card${flipped ? ' flipped' : ''}`}
145	          data-flipped={flipped ? 'true' : 'false'}
146	          onClick={handleFlip}
147	          onKeyDown={(event) => {
148	            if (event.key === 'Enter' || event.key === ' ') {
149	              event.preventDefault();
150	              handleFlip();
151	            }
152	          }}
153	          role="button"
154	          tabIndex={0}
155	          aria-label={chromeString(chromeLocale, 'practice.tapToFlip')}
156	        >
157	          <div className="flashcard-inner">
158	            <div className="flashcard-front">
159	              {currentItem ? (
160	                <>
161	                  <span className="flashcard-word">{displayLemma(currentItem.lemma)}</span>
162	                  {frontSubtitle && <span className="flashcard-subtitle">{frontSubtitle}</span>}
163	                </>
164	              ) : (
165	                <span className="flashcard-word">—</span>
166	              )}
167	            </div>
168	            <div className="flashcard-back">
169	              {currentItem ? (
170	                <>
171	                  <span className="flashcard-word">{displayGloss ?? '—'}</span>
172	                  {displayPos && (
173	                    <span className="flashcard-subtitle">{displayPos}</span>
174	                  )}
175	                  {currentExample ? (
176	                    <p className="daily-deck-example" data-testid="practice-daily-example" lang="uk">
177	                      {currentExample}
178	                      {currentExampleEn ? (
179	                        <span className="daily-deck-example-en" data-testid="practice-daily-example-en" lang="en">
180	                          {currentExampleEn}
181	                        </span>
182	                      ) : null}
183	                    </p>
184	                  ) : null}
185	                  {currentEtymology ? (
186	                    <p className="daily-deck-origin" data-testid="practice-daily-etymology" lang="uk">
187	                      <ChromeDual uk="Походження:" en="Origin:" /> {currentEtymology}
188	                    </p>
189	                  ) : null}
190	                </>
191	              ) : (
192	                <span className="flashcard-word">—</span>
193	              )}
194	            </div>
195	          </div>
196	        </div>
197	
198	        <button
199	          type="button"
200	          className="daily-deck-nav"
201	          aria-label={chromeString(chromeLocale, 'label.next')}
202	          onClick={handleNext}
203	        >
204	          ›
205	        </button>
206	      </div>
207	
208	      <div className="daily-deck-preview-actions">
209	        {currentLemmaId && currentItem?.hasAtlasEntry !== false && (
210	          <a
211	            href={atlasLemmaHref(currentLemmaId)}
212	            className="daily-deck-atlas-link"
213	            data-testid="practice-preview-atlas-link"
214	          >
215	            <ChromeText k="practice.openInAtlas" /> →
216	          </a>
217	        )}
218	        <div className="daily-deck-voice-slot" role="status" aria-live="polite">
219	          <span aria-hidden="true">🎙</span>
220	          <ChromeText k="practice.voiceSlot" />
221	        </div>
222	      </div>
223	
224	      <details
225	        className="daily-deck-details"
226	        data-testid="practice-daily-details"
227	        open={detailsOpen}
228	        onToggle={(event) => setDetailsOpen(event.currentTarget.open)}
229	      >
230	        <summary data-testid="practice-daily-summary" aria-expanded={detailsOpen} aria-controls="daily-deck-rows">
231	          <ChromeText k={detailsOpen ? 'practice.hideWords' : 'practice.showWords'} />
232	          <span className="daily-deck-counters">
233	            <span className="counter due">
234	              <span aria-hidden="true">{STATUS_META.due.glyph}</span> {rows.pendingDue.length}{' '}
235	              <ChromeText k={STATUS_META.due.labelKey} />
236	            </span>
237	            <span className="counter new">
238	              <span aria-hidden="true">{STATUS_META.new.glyph}</span> {rows.pendingNew.length}{' '}
239	              <ChromeText k={STATUS_META.new.labelKey} />
240	            </span>
241	            <span className="counter done">
242	              <span aria-hidden="true">{STATUS_META.done.glyph}</span> {rows.done.length}{' '}
243	              <ChromeText k={STATUS_META.done.labelKey} />
244	            </span>
245	          </span>
246	        </summary>
247	
248	        <ol className="daily-deck-rows" id="daily-deck-rows">
249	          {orderedRows.map((row, index) => {
250	            const meta = STATUS_META[row.state];
251	            const entry = lexemes.get(row.item.lemmaId);
252	            const rowLemma = row.item.lemma || entry?.lemma || row.item.lemmaId;
253	            const rowGloss = row.item.gloss ?? entry?.gloss ?? null;
