1	import { useEffect, useMemo } from 'react';
2	import { type PracticeStressItem, stripStressMarks } from '../lib/lexicon/srs';
3	
4	export interface PracticeStressProps {
5	  item: PracticeStressItem;
6	  selectedPosition: number | null;
7	  answerLocked: boolean;
8	  onSelect(position: number): void;
9	}
10	
11	interface NucleusInfo {
12	  nucleusIndex: number;
13	  label: string;
14	}
15	
16	export default function PracticeStress({
17	  item,
18	  selectedPosition,
19	  answerLocked,
20	  onSelect,
21	}: PracticeStressProps) {
22	  const cleanUnstressed = useMemo(() => stripStressMarks(item.unstressed), [item.unstressed]);
23	
24	  const nucleusByPosition = useMemo(() => {
25	    const map = new Map<number, NucleusInfo>();
26	    for (let index = 0; index < item.nuclei.length; index += 1) {
27	      const nucleus = item.nuclei[index];
28	      if (nucleus && !map.has(nucleus.index)) {
29	        map.set(nucleus.index, { nucleusIndex: index, label: nucleus.label });
30	      }
31	    }
32	    return map;
33	  }, [item.nuclei]);
34	
35	  const codePoints = Array.from(cleanUnstressed);
36	  const isCorrect = selectedPosition === item.stressIndex;
37	
38	  // P0-5: Digit-1..n is a redundant accelerator, matching the choice/classify
39	  // pattern — the nucleus array is already in left-to-right reading order.
40	  useEffect(() => {
41	    if (answerLocked || item.nuclei.length === 0) return undefined;
42	    const onKeyDown = (event: KeyboardEvent) => {
43	      if (event.altKey || event.ctrlKey || event.metaKey) return;
44	      const target = event.target as HTMLElement | null;
45	      if (target?.closest?.('button, a, input, textarea, select, [role="button"]')) return;
46	      const digit = Number.parseInt(event.key, 10);
47	      if (!Number.isFinite(digit) || digit < 1 || digit > item.nuclei.length) return;
48	      const nucleus = item.nuclei[digit - 1];
49	      if (!nucleus) return;
50	      event.preventDefault();
51	      onSelect(nucleus.index);
52	    };
53	    window.addEventListener('keydown', onKeyDown);
54	    return () => window.removeEventListener('keydown', onKeyDown);
55	  }, [answerLocked, item.nuclei, onSelect]);
56	
57	  return (
58	    <div className="practice-stress" data-testid="practice-stress" data-locked={answerLocked}>
59	      <p className="practice-stress-word" lang="uk" aria-label={item.stressed}>
60	        {codePoints.map((char, position) => {
61	          const nucleus = nucleusByPosition.get(position);
62	          if (nucleus) {
63	            const selected = selectedPosition === position;
64	            const isTargetStressed = position === item.stressIndex;
65	            let verdictClass = '';
66	            if (answerLocked) {
67	              if (selected) {
68	                verdictClass = isCorrect ? ' correct' : ' wrong';
69	              } else if (isTargetStressed) {
70	                verdictClass = ' correct';
71	              }
72	            }
73	            return (
74	              <button
75	                key={`nucleus-${position}`}
76	                type="button"
77	                className={`stress-vowel${verdictClass}${selected ? ' selected' : ''}`}
78	                data-nucleus-index={nucleus.nucleusIndex}
79	                data-position={position}
80	                disabled={answerLocked}
81	                aria-pressed={selected}
82	                aria-keyshortcuts={String(nucleus.nucleusIndex + 1)}
83	                onClick={() => onSelect(position)}
84	              >
85	                <span className="stress-vowel-key" aria-hidden="true">{nucleus.nucleusIndex + 1}</span>
86	                {char}
87	              </button>
88	            );
89	          }
90	          return (
